/** MyBB's Report link: a reason (optional), sent to the moderators' queue. */
export class ReportModal extends FormModal {
  reason = '';
  className() {
    return 'CR-report Modal--small';
  }
  title() {
    return t('report.title');
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "Form"
    }, m("div", {
      className: "Form-group"
    }, m("label", {
      for: "cr-reason"
    }, t('report.reason')), m("textarea", {
      id: "cr-reason",
      className: "FormControl",
      rows: 3,
      maxlength: 500,
      value: this.reason,
      oninput: e => this.reason = e.target.value
    })), m("div", {
      className: "Form-group"
    }, m(Button, {
      type: "submit",
      className: "Button Button--primary Button--block",
      loading: this.loading
    }, t('report.send')))));
  }
  onsubmit(e) {
    e.preventDefault();
    this.loading = true;
    app.store.createRecord('review-reports').save({
      subjectType: this.attrs.subjectType,
      subjectId: this.attrs.subjectId,
      reason: this.reason
    }).then(() => {
      this.hide();
      app.alerts.show({
        type: 'success'
      }, tx('report.sent'));
    }, error => {
      this.loading = false;
      this.onerror(error);
      m.redraw();
    });
  }
}
/** MyBB "Merge products", by name instead of IDs: the reviews and comments move to the item picked. */
export class MergeModal extends FormModal {
  query = '';
  results = [];
  target = null;
  timer = 0;
  className() {
    return 'CR-merge Modal--small';
  }
  title() {
    return t('merge.title', {
      name: this.attrs.item.name()
    });
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "Form"
    }, m("p", {
      className: "helpText"
    }, t('merge.help')), m("div", {
      className: "Form-group"
    }, m("label", {
      for: "cr-merge-q"
    }, t('merge.search')), m("input", {
      id: "cr-merge-q",
      className: "FormControl",
      value: this.query,
      oninput: e => this.search(e.target.value)
    })), m("div", {
      className: "CR-similar"
    }, this.results.map(item => m("button", {
      type: "button",
      className: 'CR-similar-row' + (this.target === item ? ' is-active' : ''),
      "aria-pressed": this.target === item ? 'true' : 'false',
      onclick: () => this.target = item
    }, m("span", null, item.name()), scoreTile(item.rating(), 'CR-score--sm')))), m("div", {
      className: "Form-group"
    }, m(Button, {
      type: "submit",
      className: "Button Button--primary Button--block",
      loading: this.loading,
      disabled: !this.target
    }, this.target ? t('merge.into', {
      name: this.target.name()
    }) : t('merge.pick')))));
  }
  search(value) {
    this.query = value;
    clearTimeout(this.timer);
    if (value.trim().length < 2) return;
    this.timer = window.setTimeout(() => {
      app.store.find('review-items', {
        filter: {
          q: value.trim()
        },
        page: {
          limit: 6,
          total: 0
        }
      }).then(items => this.results = items.filter(i => i !== this.attrs.item)).catch(() => this.results = []).finally(() => m.redraw());
    }, 300);
  }
  onsubmit(e) {
    e.preventDefault();
    if (!this.target) return;
    this.loading = true;
    const target = this.target;
    app.request({
      method: 'POST',
      url: `${app.forum.attribute('apiUrl')}/review-items/${this.attrs.item.id()}/merge`,
      body: {
        targetId: Number(target.id())
      }
    }).then(() => {
      this.hide();
      m.route.set(app.route('community-reviews.item', {
        id: target.urlId()
      }));
    }, error => {
      this.loading = false;
      this.onerror(error);
      m.redraw();
    });
  }
}
/** A review's photos full size, with previous and next (MyBB uses blueimp Gallery). */
export class Lightbox extends Modal {
  index = 0;
  oninit(vnode) {
    super.oninit(vnode);
    this.index = this.attrs.index;
  }
  className() {
    return 'CR-lightbox Modal--large';
  }
  title() {
    return t('lightbox.title', {
      n: this.index + 1,
      total: this.attrs.photos.length
    });
  }
  content() {
    const photos = this.attrs.photos;
    const photo = photos[this.index];
    const go = step => () => this.index = (this.index + step + photos.length) % photos.length;
    return m("div", {
      className: "Modal-body CR-lightbox-body"
    }, m("img", {
      src: photo.url,
      alt: ""
    }), photos.length > 1 ? m("div", {
      className: "CR-lightbox-nav"
    }, m(Button, {
      className: "Button",
      icon: "fas fa-chevron-left",
      onclick: go(-1)
    }, t('lightbox.prev')), m(Button, {
      className: "Button",
      icon: "fas fa-chevron-right",
      onclick: go(1)
    }, t('lightbox.next'))) : null);
  }
}
