import app from 'flarum/forum/app';
import classList from 'flarum/common/utils/classList';
import { starFill } from './starFill';

/** A has-one relationship as the model or null (Flarum returns false when it isn't loaded). */
export function one(value) {
  return value || null;
}

/**
 * 1-5 stars, the off ones drawn muted and a half star split down the middle. The one star row used everywhere
 * (cards, Top rated, the item header, each review and each criterion), so they always agree with the score.
 */
export function stars(value, className = '') {
  const fills = starFill(value);
  const label = (Math.round((Number(value) || 0) * 2) / 2).toString();
  return m("span", {
    className: classList('CR-stars', className),
    "aria-label": `${label} / 5`,
    role: "img"
  }, fills.map(fill => m("span", {
    className: `CR-star is-${fill}`,
    "aria-hidden": "true"
  }, "\u2605")));
}

/** great ≥ 4.5, good ≥ 3.5, mid below; no rating yet = new. */
export function scoreClass(rating, ranked = true) {
  if (rating === null || rating === undefined || !ranked) return 'is-new';
  if (rating >= 4.5) return 'is-great';
  if (rating >= 3.5) return 'is-good';
  return 'is-mid';
}
export function scoreTile(rating, className = '', ranked = true) {
  return m("span", {
    className: classList('CR-score', scoreClass(rating, ranked), className)
  }, rating === null || rating === undefined ? '–' : rating.toFixed(1));
}

/** An item's picture: its thumbnail, or a placeholder in the category's colour. */
export function art(item, full = false) {
  const url = full ? item.photoUrl() || item.thumbnailUrl() : item.thumbnailUrl();
  const color = one(item.category())?.color?.() || '';
  return m("span", {
    className: classList('CR-art', !url && 'CR-art--empty'),
    style: !url && color ? {
      '--cr-tint': color
    } : undefined
  }, url ? m("img", {
    src: url,
    alt: "",
    loading: "lazy"
  }) : m("i", {
    className: classList(one(item.category())?.icon?.() || 'fas fa-box-open'),
    "aria-hidden": "true"
  }));
}

/** A short count: 980, 2.4k, 96k. */
export function count(n) {
  if (n < 1000) return String(n);
  if (n < 10000) return (n / 1000).toFixed(1).replace(/\.0$/, '') + 'k';
  return Math.round(n / 1000) + 'k';
}

/** Whether an item has enough reviews to be ranked (the admin's threshold). */
export function ranked(item) {
  const all = app.forum.attribute('communityReviews') || {};
  return item.reviewCount() >= Number(all.rank_min_reviews || 1);
}
flarum.reg.add('ernestdefoe-community-reviews', 'forum/ui/bits', { one: one,stars: stars,scoreClass: scoreClass,scoreTile: scoreTile,art: art,count: count,ranked: ranked, });